import unittest


def maximum(arr, k):
    if k == 0:
        return []
    arr.sort()
    ans = arr[-k:]
    return ans


class TestMaximum(unittest.TestCase):

    def test_k_zero_returns_empty_list(self):
        self.assertEqual(maximum([1, 2, 3], 0), [])

    def test_basic_case(self):
        self.assertEqual(maximum([1, 2, 3, 4, 5], 3), [3, 4, 5])

    def test_k_equals_length(self):
        self.assertEqual(maximum([1, 2, 3], 3), [1, 2, 3])

    def test_k_one(self):
        self.assertEqual(maximum([5, 1, 9, 3], 1), [9])

    def test_unsorted_input(self):
        self.assertEqual(maximum([-10, 7, 3, 20, 4], 2), [7, 20])

    def test_with_duplicates(self):
        self.assertEqual(maximum([4, -4, 4, 1, 2], 2), [4, 4])

    def test_all_negative_numbers(self):
        self.assertEqual(maximum([-5, -2, -8, -1], 2), [-2, -1])

    def test_empty_array(self):
        self.assertEqual(maximum([], 1), [])

    def test_k_larger_than_array(self):
        # arr[-k:] with k > len returns whole sorted array
        self.assertEqual(maximum([3, 1, 2], 5), [1, 2, 3])

    def test_single_element_array(self):
        self.assertEqual(maximum([42], 1), [42])

    def test_result_is_sorted_ascending(self):
        result = maximum([9, 3, 7, 1, 8], 3)
        self.assertEqual(result, sorted(result))

    def test_input_array_is_modified_in_place(self):
        arr = [3, 1, 2]
        maximum(arr, 2)
        self.assertEqual(arr, [1, 2, 3])  # sort() mutates input


if __name__ == "__main__":
    unittest.main()
```

